<script lang="ts">import NavIcon from './NavIcon.svelte';let {active,navigate}:{active:string,navigate:(route:string)=>void}=$props();const tabs=[{route:'today',label:'Today',icon:'today'},{route:'plan',label:'Plan',icon:'plan'},{route:'training',label:'Training',icon:'training'},{route:'health',label:'Health',icon:'health'},{route:'progress',label:'Progress',icon:'progress'}] as const;</script><nav class="tabs" aria-label="Main navigation">{#each tabs as tab}<button class="tab" class:on={active===tab.route} aria-current={active===tab.route?'page':undefined} onclick={()=>navigate(tab.route)}><span class="tab-icon"><NavIcon name={tab.icon} size={23}/></span>{tab.label}</button>{/each}</nav>
